"""Sortie Z4a, batch 3: the character-sum orthogonality at integer arguments
(MeanValue sum_char_mul_conj) and the unit-group Parseval (LargeSieve parseval_units)."""
import sys, os; sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..')); from tm import *
from z4alib import *
only = sys.argv[1:]
def run(w):
    if only and w.label not in only: return True
    return w.run()

F0 = FZO('N'); CRN = CR('N'); DN = DB('N'); L = LZ('N'); BN = BZ('N'); ZN = '( Z/nZ ` N )'
PHI = '( phi ` N )'
def XL(a, x='x'): return EV(x, 'N', a)

# ---- dchrsumuv
A0 = '( N e. NN /\\ ( U e. ZZ /\\ ( U gcd N ) = 1 ) /\\ ( V e. ZZ /\\ ( V gcd N ) = 1 ) )'
VB = '( V x. b )'; UB = '( U x. b )'
DVB = 'N || ( %s - 1 )' % VB
BODY = '( %s x. %s )' % (XL('U'), CJ(XL('V'))); SUMX = 'sum_ x e. %s %s' % (DN, BODY)
IFD = 'if ( N || ( U - V ) , %s , 0 )' % PHI
w = W('dchrsumuv', 'Orthogonality of the Dirichlet characters mod N summed over the characters, at two integers coprime to N: the sum of x ( U ) conj x ( V ) is phi ( N ) when U = V mod N and 0 otherwise (MeanValue sum_char_mul_conj at coprime arguments; set.mm sumdchr).')
n = w.s([], 'simp1', '( %s -> N e. NN )' % A0)
uc = w.s([], 'simp2', '( %s -> ( U e. ZZ /\\ ( U gcd N ) = 1 ) )' % A0); u = w.s([uc], 'simpld', '( %s -> U e. ZZ )' % A0)
vc = w.s([], 'simp3', '( %s -> ( V e. ZZ /\\ ( V gcd N ) = 1 ) )' % A0); v = w.s([vc], 'simpld', '( %s -> V e. ZZ )' % A0); vcop = w.s([vc], 'simprd', '( %s -> ( V gcd N ) = 1 )' % A0)
ex = w.s([n, v, vcop, w.inst('zinvex')], 'syl3anc', '( %s -> E. b e. ZZ %s )' % (A0, DVB))
Ab = '( %s /\\ ( b e. ZZ /\\ %s ) )' % (A0, DVB)
bd = w.s([], 'simpr', '( %s -> ( b e. ZZ /\\ %s ) )' % (Ab, DVB)); bz = w.s([bd], 'simpld', '( %s -> b e. ZZ )' % Ab); dvb = w.s([bd], 'simprd', '( %s -> %s )' % (Ab, DVB))
nb = w.s([n], 'adantr', '( %s -> N e. NN )' % Ab); ub = w.s([u], 'adantr', '( %s -> U e. ZZ )' % Ab); vb = w.s([v], 'adantr', '( %s -> V e. ZZ )' % Ab)
Ax = '( %s /\\ x e. %s )' % (Ab, DN)
xmem = w.s([], 'simpr', '( %s -> x e. %s )' % (Ax, DN))
hcx = w.s([w.s([nb], 'adantr', '( %s -> N e. NN )' % Ax), xmem], 'jca', '( %s -> ( N e. NN /\\ x e. %s ) )' % (Ax, DN))
cj = w.s([hcx, w.s([w.s([vb], 'adantr', '( %s -> V e. ZZ )' % Ax), w.s([bz], 'adantr', '( %s -> b e. ZZ )' % Ax)], 'jca', '( %s -> ( V e. ZZ /\\ b e. ZZ ) )' % Ax), w.s([dvb], 'adantr', '( %s -> %s )' % (Ax, DVB)), w.inst('dchrcjinv')], 'syl3anc', '( %s -> %s = %s )' % (Ax, CJ(XL('V')), XL('b')))
g, z, d, l = dchyp(w)
mul = w.s([g, z, d, l, xmem, w.s([ub], 'adantr', '( %s -> U e. ZZ )' % Ax), w.s([bz], 'adantr', '( %s -> b e. ZZ )' % Ax)], 'dchrzrhmul', '( %s -> %s = ( %s x. %s ) )' % (Ax, XL(UB), XL('U'), XL('b')))
t = w.s([w.s([cj], 'oveq2d', '( %s -> %s = ( %s x. %s ) )' % (Ax, BODY, XL('U'), XL('b'))), w.s([mul], 'eqcomd', '( %s -> ( %s x. %s ) = %s )' % (Ax, XL('U'), XL('b'), XL(UB)))], 'eqtrd', '( %s -> %s = %s )' % (Ax, BODY, XL(UB)))
s1 = w.s([t], 'sumeq2dv', '( %s -> %s = sum_ x e. %s %s )' % (Ab, SUMX, DN, XL(UB)))
ubz = w.s([ub, bz], 'zmulcld', '( %s -> %s e. ZZ )' % (Ab, UB))
el = zrh_el(w, Ab, nb, ubz, 'N', UB)
one = w.s([], 'eqid', '( 1r ` %s ) = ( 1r ` %s )' % (ZN, ZN)); bb = w.s([], 'eqid', '%s = %s' % (BN, BN))
sd = w.s([g, d, z, one, bb, nb, el], 'sumdchr', '( %s -> sum_ x e. %s ( x ` ( %s ` %s ) ) = if ( ( %s ` %s ) = ( 1r ` %s ) , %s , 0 ) )' % (Ab, DN, L, UB, L, UB, ZN, PHI))
# the condition: ( L ` UB ) = 1r <-> N || ( U - V )
n0 = w.s([nb], 'nnnn0d', '( %s -> N e. NN0 )' % Ab)
ring = w.s([w.s([n0, w.s([z], 'zncrng', '( N e. NN0 -> %s e. CRing )' % ZN)], 'syl', '( %s -> %s e. CRing )' % (Ab, ZN)), w.inst('crngring')], 'syl', '( %s -> %s e. Ring )' % (Ab, ZN))
l1 = w.s([ring, w.s([l, one], 'zrh1', '( %s e. Ring -> ( %s ` 1 ) = ( 1r ` %s ) )' % (ZN, L, ZN))], 'syl', '( %s -> ( %s ` 1 ) = ( 1r ` %s ) )' % (Ab, L, ZN))
c1 = w.s([w.s([l1], 'eqcomd', '( %s -> ( 1r ` %s ) = ( %s ` 1 ) )' % (Ab, ZN, L))], 'eqeq2d', '( %s -> ( ( %s ` %s ) = ( 1r ` %s ) <-> ( %s ` %s ) = ( %s ` 1 ) ) )' % (Ab, L, UB, ZN, L, UB, L))
c2 = w.s([n0, ubz, w.s([], '1zzd', '( %s -> 1 e. ZZ )' % Ab), w.s([z, l], 'zndvds', '( ( N e. NN0 /\\ %s e. ZZ /\\ 1 e. ZZ ) -> ( ( %s ` %s ) = ( %s ` 1 ) <-> N || ( %s - 1 ) ) )' % (UB, L, UB, L, UB))], 'syl3anc', '( %s -> ( ( %s ` %s ) = ( %s ` 1 ) <-> N || ( %s - 1 ) ) )' % (Ab, L, UB, L, UB))
# N || ( UB - 1 ) <-> N || ( ( U - V ) x. b )
ucn = w.s([ub], 'zcnd', '( %s -> U e. CC )' % Ab); vcn = w.s([vb], 'zcnd', '( %s -> V e. CC )' % Ab); bcn = w.s([bz], 'zcnd', '( %s -> b e. CC )' % Ab)
UVB = '( ( U - V ) x. b )'
i1 = w.s([w.s([ucn, vcn, bcn], 'subdird', '( %s -> %s = ( %s - %s ) )' % (Ab, UVB, UB, VB))], 'oveq1d', '( %s -> ( %s + ( %s - 1 ) ) = ( ( %s - %s ) + ( %s - 1 ) ) )' % (Ab, UVB, VB, UB, VB, VB))
i2 = w.s([w.s([ucn, bcn], 'mulcld', '( %s -> %s e. CC )' % (Ab, UB)), w.s([vcn, bcn], 'mulcld', '( %s -> %s e. CC )' % (Ab, VB)), w.s([], '1cnd', '( %s -> 1 e. CC )' % Ab)], 'npncand', '( %s -> ( ( %s - %s ) + ( %s - 1 ) ) = ( %s - 1 ) )' % (Ab, UB, VB, VB, UB))
ident = w.s([i1, i2], 'eqtrd', '( %s -> ( %s + ( %s - 1 ) ) = ( %s - 1 ) )' % (Ab, UVB, VB, UB))
nz = w.s([nb], 'nnzd', '( %s -> N e. ZZ )' % Ab)
uvbz = w.s([w.s([ub, vb], 'zsubcld', '( %s -> ( U - V ) e. ZZ )' % Ab), bz], 'zmulcld', '( %s -> %s e. ZZ )' % (Ab, UVB))
vb1z = w.s([w.s([vb, bz], 'zmulcld', '( %s -> %s e. ZZ )' % (Ab, VB)), w.s([], '1zzd', '( %s -> 1 e. ZZ )' % Ab)], 'zsubcld', '( %s -> ( %s - 1 ) e. ZZ )' % (Ab, VB))
c3 = w.s([nz, uvbz, w.s([vb1z, dvb], 'jca', '( %s -> ( ( %s - 1 ) e. ZZ /\\ %s ) )' % (Ab, VB, DVB)), w.inst('dvdsadd2b')], 'syl3anc', '( %s -> ( N || %s <-> N || ( ( %s - 1 ) + %s ) ) )' % (Ab, UVB, VB, UVB))
com = w.s([w.s([vb1z], 'zcnd', '( %s -> ( %s - 1 ) e. CC )' % (Ab, VB)), w.s([uvbz], 'zcnd', '( %s -> %s e. CC )' % (Ab, UVB))], 'addcomd', '( %s -> ( ( %s - 1 ) + %s ) = ( %s + ( %s - 1 ) ) )' % (Ab, VB, UVB, UVB, VB))
c4 = w.s([w.s([com, ident], 'eqtrd', '( %s -> ( ( %s - 1 ) + %s ) = ( %s - 1 ) )' % (Ab, VB, UVB, UB))], 'breq2d', '( %s -> ( N || ( ( %s - 1 ) + %s ) <-> N || ( %s - 1 ) ) )' % (Ab, VB, UVB, UB))
c5 = w.s([w.s([c3, c4], 'bitrd', '( %s -> ( N || %s <-> N || ( %s - 1 ) ) )' % (Ab, UVB, UB))], 'bicomd', '( %s -> ( N || ( %s - 1 ) <-> N || %s ) )' % (Ab, UB, UVB))
# N || ( ( U - V ) x. b ) <-> N || ( U - V ) by coprimality of b
bcop = w.s([nb, w.s([vb, bz], 'jca', '( %s -> ( V e. ZZ /\\ b e. ZZ ) )' % Ab), dvb, w.inst('dvdsinvcop')], 'syl3anc', '( %s -> ( b gcd N ) = 1 )' % Ab)
nbcop = w.s([w.s([nz, bz], 'gcdcomd', '( %s -> ( N gcd b ) = ( b gcd N ) )' % Ab), bcop], 'eqtrd', '( %s -> ( N gcd b ) = 1 )' % Ab)
uvz = w.s([ub, vb], 'zsubcld', '( %s -> ( U - V ) e. ZZ )' % Ab)
# coprmdvds: ( ( K || ( M x. N ) /\ ( K gcd M ) = 1 ) -> K || N ) with K = N, M = b, N = ( U - V ): the product is ( b x. ( U - V ) )
fwd0 = w.s([nz, bz, uvz, w.inst('coprmdvds')], 'syl3anc', '( %s -> ( ( N || ( b x. ( U - V ) ) /\\ ( N gcd b ) = 1 ) -> N || ( U - V ) ) )' % Ab)
fwd1 = w.s([nbcop, fwd0], 'mpan2d', '( %s -> ( N || ( b x. ( U - V ) ) -> N || ( U - V ) ) )' % Ab)
swap = w.s([w.s([uvz], 'zcnd', '( %s -> ( U - V ) e. CC )' % Ab), bcn], 'mulcomd', '( %s -> %s = ( b x. ( U - V ) ) )' % (Ab, UVB))
fwd = w.s([w.s([swap], 'breq2d', '( %s -> ( N || %s <-> N || ( b x. ( U - V ) ) ) )' % (Ab, UVB)), fwd1], 'sylbid', '( %s -> ( N || %s -> N || ( U - V ) ) )' % (Ab, UVB))
bwd = w.s([nz, uvz, bz, w.inst('dvdsmultr1')], 'syl3anc', '( %s -> ( N || ( U - V ) -> N || %s ) )' % (Ab, UVB))
c6 = w.s([fwd, bwd], 'impbid', '( %s -> ( N || %s <-> N || ( U - V ) ) )' % (Ab, UVB))
cond = w.s([w.s([w.s([c1, c2], 'bitrd', '( %s -> ( ( %s ` %s ) = ( 1r ` %s ) <-> N || ( %s - 1 ) ) )' % (Ab, L, UB, ZN, UB)), c5], 'bitrd', '( %s -> ( ( %s ` %s ) = ( 1r ` %s ) <-> N || %s ) )' % (Ab, L, UB, ZN, UVB)), c6], 'bitrd', '( %s -> ( ( %s ` %s ) = ( 1r ` %s ) <-> N || ( U - V ) ) )' % (Ab, L, UB, ZN))
ifb = w.s([cond], 'ifbid', '( %s -> if ( ( %s ` %s ) = ( 1r ` %s ) , %s , 0 ) = %s )' % (Ab, L, UB, ZN, PHI, IFD))
concl = w.s([w.s([s1, sd], 'eqtrd', '( %s -> %s = if ( ( %s ` %s ) = ( 1r ` %s ) , %s , 0 ) )' % (Ab, SUMX, L, UB, ZN, PHI)), ifb], 'eqtrd', '( %s -> %s = %s )' % (Ab, SUMX, IFD))
w.qed([ex, concl], 'rexlimddv', '( %s -> %s = %s )' % (A0, SUMX, IFD)); run(w)

# ---- dchrparulem1: S x. conj S as a double sum, for one character X
H0 = '( N e. NN /\\ G : %s --> CC )' % CRN
A1 = '( %s /\\ X e. %s )' % (H0, DN)
def GU(u): return '( G ` %s )' % u
def TU(u, x='X'): return '( %s x. %s )' % (XL(u, x), GU(u))
def GG(u, v): return '( %s x. %s )' % (GU(u), CJ(GU(v)))
def XX(u, v, x='X'): return '( %s x. %s )' % (XL(u, x), CJ(XL(v, x)))
def TT(u, v, x='X'): return '( %s x. %s )' % (GG(u, v), XX(u, v, x))
S = 'sum_ u e. %s %s' % (CRN, TU('u'))
def SS(body, u='u', v='v'): return 'sum_ %s e. %s sum_ %s e. %s %s' % (u, CRN, v, CRN, body)
w = W('dchrparulem1', 'Lemma for dchrparu: the character-linear form times its conjugate is the double sum over the coprime residues of G ( u ) conj G ( v ) X ( u ) conj X ( v ) (Lean hexp).')
h0 = w.s([], 'simpl', '( %s -> %s )' % (A1, H0)); n = w.s([h0], 'simpld', '( %s -> N e. NN )' % A1); gf = w.s([h0], 'simprd', '( %s -> G : %s --> CC )' % (A1, CRN)); x = w.s([], 'simpr', '( %s -> X e. %s )' % (A1, DN))
g, z, d, l = dchyp(w)
crf = crfin(w, A1)
def tcl(ante, xst, gst, umem, u):
    uz = crz(w, ante, umem, u)
    xu = w.s([g, z, d, l, xst, uz], 'dchrzrhcl', '( %s -> %s e. CC )' % (ante, XL(u, 'X')))
    gu = w.s([gst, umem], 'ffvelcdmd', '( %s -> %s e. CC )' % (ante, GU(u)))
    return xu, gu, w.s([xu, gu], 'mulcld', '( %s -> %s e. CC )' % (ante, TU(u)))
Au = '( %s /\\ u e. %s )' % (A1, CRN)
xu, gu, tu = tcl(Au, w.s([x], 'adantr', '( %s -> X e. %s )' % (Au, DN)), w.s([gf], 'adantr', '( %s -> G : %s --> CC )' % (Au, CRN)), w.s([], 'simpr', '( %s -> u e. %s )' % (Au, CRN)), 'u')
cjs = w.s([crf, tu], 'fsumcj', '( %s -> %s = sum_ u e. %s %s )' % (A1, CJ(S), CRN, CJ(TU('u'))))
cv, TV = cbvsum(w, CRN, CJ(TU('u')), 'u', 'v')
assert TV == CJ(TU('v')), TV
SV = 'sum_ v e. %s %s' % (CRN, TV)
lhs = w.s([w.s([cjs, w.s([cv], 'a1i', '( %s -> sum_ u e. %s %s = %s )' % (A1, CRN, CJ(TU('u')), SV))], 'eqtrd', '( %s -> %s = %s )' % (A1, CJ(S), SV))], 'oveq2d', '( %s -> ( %s x. %s ) = ( %s x. %s ) )' % (A1, S, CJ(S), S, SV))
Av = '( %s /\\ v e. %s )' % (A1, CRN)
xv, gv, tv = tcl(Av, w.s([x], 'adantr', '( %s -> X e. %s )' % (Av, DN)), w.s([gf], 'adantr', '( %s -> G : %s --> CC )' % (Av, CRN)), w.s([], 'simpr', '( %s -> v e. %s )' % (Av, CRN)), 'v')
tvc = w.s([tv], 'cjcld', '( %s -> %s e. CC )' % (Av, TV))
PROD = '( %s x. %s )' % (TU('u'), TV)
m2 = w.s([crf, crf, tu, tvc], 'fsum2mul', '( %s -> %s = ( %s x. %s ) )' % (A1, SS(PROD), S, SV))
Auv = '( %s /\\ v e. %s )' % (Au, CRN)
xu2, gu2, _ = tcl(Auv, w.s([x], 'ad2antrr', '( %s -> X e. %s )' % (Auv, DN)), w.s([gf], 'ad2antrr', '( %s -> G : %s --> CC )' % (Auv, CRN)), w.s([], 'simplr', '( %s -> u e. %s )' % (Auv, CRN)), 'u')
xv2, gv2, _ = tcl(Auv, w.s([x], 'ad2antrr', '( %s -> X e. %s )' % (Auv, DN)), w.s([gf], 'ad2antrr', '( %s -> G : %s --> CC )' % (Auv, CRN)), w.s([], 'simpr', '( %s -> v e. %s )' % (Auv, CRN)), 'v')
e1 = w.s([w.s([xv2, gv2], 'cjmuld', '( %s -> %s = ( %s x. %s ) )' % (Auv, TV, CJ(XL('v', 'X')), CJ(GU('v'))))], 'oveq2d', '( %s -> %s = ( %s x. ( %s x. %s ) ) )' % (Auv, PROD, TU('u'), CJ(XL('v', 'X')), CJ(GU('v'))))
cxv = w.s([xv2], 'cjcld', '( %s -> %s e. CC )' % (Auv, CJ(XL('v', 'X')))); cgv = w.s([gv2], 'cjcld', '( %s -> %s e. CC )' % (Auv, CJ(GU('v'))))
e2 = w.s([xu2, gu2, cxv, cgv], 'mul4d', '( %s -> ( %s x. ( %s x. %s ) ) = ( %s x. %s ) )' % (Auv, TU('u'), CJ(XL('v', 'X')), CJ(GU('v')), XX('u', 'v'), GG('u', 'v')))
e3 = w.s([w.s([xu2, cxv], 'mulcld', '( %s -> %s e. CC )' % (Auv, XX('u', 'v'))), w.s([gu2, cgv], 'mulcld', '( %s -> %s e. CC )' % (Auv, GG('u', 'v')))], 'mulcomd', '( %s -> ( %s x. %s ) = %s )' % (Auv, XX('u', 'v'), GG('u', 'v'), TT('u', 'v')))
summand = w.s([w.s([e1, e2], 'eqtrd', '( %s -> %s = ( %s x. %s ) )' % (Auv, PROD, XX('u', 'v'), GG('u', 'v'))), e3], 'eqtrd', '( %s -> %s = %s )' % (Auv, PROD, TT('u', 'v')))
s2 = w.s([w.s([summand], 'sumeq2dv', '( %s -> sum_ v e. %s %s = sum_ v e. %s %s )' % (Au, CRN, PROD, CRN, TT('u', 'v')))], 'sumeq2dv', '( %s -> %s = %s )' % (A1, SS(PROD), SS(TT('u', 'v'))))
w.qed([w.s([lhs, w.s([m2], 'eqcomd', '( %s -> ( %s x. %s ) = %s )' % (A1, S, SV, SS(PROD)))], 'eqtrd', '( %s -> ( %s x. %s ) = %s )' % (A1, S, CJ(S), SS(PROD))), s2], 'eqtrd', '( %s -> ( %s x. %s ) = %s )' % (A1, S, CJ(S), SS(TT('u', 'v')))); run(w)

# ---- dchrparulem2: the character sum inside
Sx = 'sum_ u e. %s %s' % (CRN, TU('u', 'x'))
TTx = TT('u', 'v', 'x')
IFUV = 'if ( N || ( u - v ) , %s , 0 )' % PHI
DELTA = '( %s x. %s )' % (GG('u', 'v'), IFUV)
w = W('dchrparulem2', 'Lemma for dchrparu: summing the expanded forms over all characters and applying the orthogonality dchrsumuv inside (Lean hC, hchar).')
n = w.s([], 'simpl', '( %s -> N e. NN )' % H0); gf = w.s([], 'simpr', '( %s -> G : %s --> CC )' % (H0, CRN))
g, z, d, l = dchyp(w)
crf = crfin(w, H0)
dfi = w.s([n, w.s([g, d], 'dchrfi', '( N e. NN -> %s e. Fin )' % DN)], 'syl', '( %s -> %s e. Fin )' % (H0, DN))
Ax = '( %s /\\ x e. %s )' % (H0, DN)
l1 = w.s([], 'dchrparulem1', '( %s -> ( %s x. %s ) = %s )' % (Ax, Sx, CJ(Sx), SS(TTx)))
s1 = w.s([l1], 'sumeq2dv', '( %s -> sum_ x e. %s ( %s x. %s ) = sum_ x e. %s %s )' % (H0, DN, Sx, CJ(Sx), DN, SS(TTx)))
def ttcl(ante, nst, gst, xmem, umem, vmem):
    uz = crz(w, ante, umem, 'u'); vz = crz(w, ante, vmem, 'v')
    xu = w.s([g, z, d, l, xmem, uz], 'dchrzrhcl', '( %s -> %s e. CC )' % (ante, XL('u'))); xv = w.s([g, z, d, l, xmem, vz], 'dchrzrhcl', '( %s -> %s e. CC )' % (ante, XL('v')))
    gu = w.s([gst, umem], 'ffvelcdmd', '( %s -> %s e. CC )' % (ante, GU('u'))); gv = w.s([gst, vmem], 'ffvelcdmd', '( %s -> %s e. CC )' % (ante, GU('v')))
    gg = w.s([gu, w.s([gv], 'cjcld', '( %s -> %s e. CC )' % (ante, CJ(GU('v'))))], 'mulcld', '( %s -> %s e. CC )' % (ante, GG('u', 'v')))
    xx = w.s([xu, w.s([xv], 'cjcld', '( %s -> %s e. CC )' % (ante, CJ(XL('v'))))], 'mulcld', '( %s -> %s e. CC )' % (ante, XX('u', 'v', 'x')))
    return gg, xx, w.s([gg, xx], 'mulcld', '( %s -> %s e. CC )' % (ante, TTx))
# swap x and u
Axu = '( %s /\\ ( x e. %s /\\ u e. %s ) )' % (H0, DN, CRN); Axuv = '( %s /\\ v e. %s )' % (Axu, CRN)
xu_ = w.s([], 'simpr', '( %s -> ( x e. %s /\\ u e. %s ) )' % (Axu, DN, CRN))
_, _, tt1 = ttcl(Axuv, w.s([n], 'ad2antrr', '( %s -> N e. NN )' % Axuv), w.s([gf], 'ad2antrr', '( %s -> G : %s --> CC )' % (Axuv, CRN)), w.s([w.s([xu_], 'simpld', '( %s -> x e. %s )' % (Axu, DN))], 'adantr', '( %s -> x e. %s )' % (Axuv, DN)), w.s([w.s([xu_], 'simprd', '( %s -> u e. %s )' % (Axu, CRN))], 'adantr', '( %s -> u e. %s )' % (Axuv, CRN)), w.s([], 'simpr', '( %s -> v e. %s )' % (Axuv, CRN)))
scl1 = w.s([w.s([crf], 'adantr', '( %s -> %s e. Fin )' % (Axu, CRN)), tt1], 'fsumcl', '( %s -> sum_ v e. %s %s e. CC )' % (Axu, CRN, TTx))
SVT = 'sum_ v e. %s %s' % (CRN, TTx)
com1 = w.s([dfi, crf, scl1], 'fsumcom', '( %s -> sum_ x e. %s sum_ u e. %s %s = sum_ u e. %s sum_ x e. %s %s )' % (H0, DN, CRN, SVT, CRN, DN, SVT))
# under u: swap x and v
