_, _, tt2 = ttcl(Auxv, w.s([n], 'ad2antrr', '( %s -> N e. NN )' % Auxv), w.s([gf], 'ad2antrr', '( %s -> G : %s --> CC )' % (Auxv, CRN)), w.s([xv_], 'simpld', '( %s -> x e. %s )' % (Auxv, DN)), w.s([], 'simplr', '( %s -> u e. %s )' % (Auxv, CRN)), w.s([xv_], 'simprd', '( %s -> v e. %s )' % (Auxv, CRN)))
com2 = w.s([w.s([dfi], 'adantr', '( %s -> %s e. Fin )' % (Au, DN)), w.s([crf], 'adantr', '( %s -> %s e. Fin )' % (Au, CRN)), tt2], 'fsumcom', '( %s -> sum_ x e. %s %s = sum_ v e. %s sum_ x e. %s %s )' % (Au, DN, SVT, CRN, DN, TTx))
# under ( u , v ): the inner character sum
Auv = '( %s /\\ v e. %s )' % (Au, CRN); Auvx = '( %s /\\ x e. %s )' % (Auv, DN)
umem = w.s([], 'simplr', '( %s -> u e. %s )' % (Auv, CRN)); vmem = w.s([], 'simpr', '( %s -> v e. %s )' % (Auv, CRN))
nuv = w.s([n], 'ad2antrr', '( %s -> N e. NN )' % Auv); guv = w.s([gf], 'ad2antrr', '( %s -> G : %s --> CC )' % (Auv, CRN))
gg3, xx3, _ = ttcl(Auvx, w.s([nuv], 'adantr', '( %s -> N e. NN )' % Auvx), w.s([guv], 'adantr', '( %s -> G : %s --> CC )' % (Auvx, CRN)), w.s([], 'simpr', '( %s -> x e. %s )' % (Auvx, DN)), w.s([umem], 'adantr', '( %s -> u e. %s )' % (Auvx, CRN)), w.s([vmem], 'adantr', '( %s -> v e. %s )' % (Auvx, CRN)))
gg0 = w.s([w.s([guv, umem], 'ffvelcdmd', '( %s -> %s e. CC )' % (Auv, GU('u'))), w.s([w.s([guv, vmem], 'ffvelcdmd', '( %s -> %s e. CC )' % (Auv, GU('v')))], 'cjcld', '( %s -> %s e. CC )' % (Auv, CJ(GU('v'))))], 'mulcld', '( %s -> %s e. CC )' % (Auv, GG('u', 'v')))
SXX = 'sum_ x e. %s %s' % (DN, XX('u', 'v', 'x'))
