inner = w.s([w.s([mc], 'eqcomd', '( %s -> sum_ x e. %s %s = ( %s x. %s ) )' % (Auv, DN, TTx, GG('u', 'v'), SXX)), w.s([orth], 'oveq2d', '( %s -> ( %s x. %s ) = %s )' % (Auv, GG('u', 'v'), SXX, DELTA))], 'eqtrd', '( %s -> sum_ x e. %s %s = %s )' % (Auv, DN, TTx, DELTA))
s3 = w.s([w.s([com2, w.s([inner], 'sumeq2dv', '( %s -> sum_ v e. %s sum_ x e. %s %s = sum_ v e. %s %s )' % (Au, CRN, DN, TTx, CRN, DELTA))], 'eqtrd', '( %s -> sum_ x e. %s %s = sum_ v e. %s %s )' % (Au, DN, SVT, CRN, DELTA))], 'sumeq2dv', '( %s -> sum_ u e. %s sum_ x e. %s %s = %s )' % (H0, CRN, DN, SVT, SS(DELTA)))
