# ---- dchrparulem3: the delta collapses
Au = '( %s /\\ u e. %s )' % (H0, CRN); Auv = '( %s /\\ v e. %s )' % (Au, CRN)
GGP = '( %s x. %s )' % (GG('u', 'v'), PHI); GGU = '( %s x. %s )' % (GG('u', 'u'), PHI)
w = W('dchrparulem3', 'Lemma for dchrparu: the delta sum over v collapses to phi ( N ) G ( u ) conj G ( u ) (Lean Finset.sum_eq_single).')
n = w.s([w.s([], 'simpl', '( %s -> %s )' % (Au, H0))], 'simpld', '( %s -> N e. NN )' % Au); gf = w.s([w.s([], 'simpl', '( %s -> %s )' % (Au, H0))], 'simprd', '( %s -> G : %s --> CC )' % (Au, CRN)); umem = w.s([], 'simpr', '( %s -> u e. %s )' % (Au, CRN))
vmem = w.s([], 'simpr', '( %s -> v e. %s )' % (Auv, CRN))
uF = w.s([w.s([umem], 'adantr', '( %s -> u e. %s )' % (Auv, CRN)), w.inst('elrabi')], 'syl', '( %s -> u e. %s )' % (Auv, F0)); vF = w.s([vmem, w.inst('elrabi')], 'syl', '( %s -> v e. %s )' % (Auv, F0))
ce = w.s([w.s([n], 'adantr', '( %s -> N e. NN )' % Auv), uF, vF, w.inst('fzocongeq0')], 'syl3anc', '( %s -> ( N || ( u - v ) <-> u = v ) )' % Auv)
ce2 = w.s([ce, w.s([w.s([], 'eqcom', '( u = v <-> v = u )')], 'a1i', '( %s -> ( u = v <-> v = u ) )' % Auv)], 'bitrd', '( %s -> ( N || ( u - v ) <-> v = u ) )' % Auv)
ifb = w.s([w.s([ce2], 'ifbid', '( %s -> %s = if ( v = u , %s , 0 ) )' % (Auv, IFUV, PHI))], 'oveq2d', '( %s -> %s = ( %s x. if ( v = u , %s , 0 ) ) )' % (Auv, DELTA, GG('u', 'v'), PHI))
ov = w.s([w.s([], 'ovif2', '( %s x. if ( v = u , %s , 0 ) ) = if ( v = u , %s , ( %s x. 0 ) )' % (GG('u', 'v'), PHI, GGP, GG('u', 'v')))], 'a1i', '( %s -> ( %s x. if ( v = u , %s , 0 ) ) = if ( v = u , %s , ( %s x. 0 ) ) )' % (Auv, GG('u', 'v'), PHI, GGP, GG('u', 'v')))
gfv = w.s([gf], 'adantr', '( %s -> G : %s --> CC )' % (Auv, CRN))
gg = w.s([w.s([gfv, w.s([umem], 'adantr', '( %s -> u e. %s )' % (Auv, CRN))], 'ffvelcdmd', '( %s -> %s e. CC )' % (Auv, GU('u'))), w.s([w.s([gfv, vmem], 'ffvelcdmd', '( %s -> %s e. CC )' % (Auv, GU('v')))], 'cjcld', '( %s -> %s e. CC )' % (Auv, CJ(GU('v'))))], 'mulcld', '( %s -> %s e. CC )' % (Auv, GG('u', 'v')))
z0 = w.s([w.s([gg], 'mul01d', '( %s -> ( %s x. 0 ) = 0 )' % (Auv, GG('u', 'v')))], 'ifeq2d', '( %s -> if ( v = u , %s , ( %s x. 0 ) ) = if ( v = u , %s , 0 ) )' % (Auv, GGP, GG('u', 'v'), GGP))
summand = w.s([w.s([ifb, ov], 'eqtrd', '( %s -> %s = if ( v = u , %s , ( %s x. 0 ) ) )' % (Auv, DELTA, GGP, GG('u', 'v'))), z0], 'eqtrd', '( %s -> %s = if ( v = u , %s , 0 ) )' % (Auv, DELTA, GGP))
s1 = w.s([summand], 'sumeq2dv', '( %s -> sum_ v e. %s %s = sum_ v e. %s if ( v = u , %s , 0 ) )' % (Au, CRN, DELTA, CRN, GGP))
sub = w.s([w.s([w.s([w.s([], 'fveq2', '( v = u -> %s = %s )' % (GU('v'), GU('u')))], 'fveq2d', '( v = u -> %s = %s )' % (CJ(GU('v')), CJ(GU('u'))))], 'oveq2d', '( v = u -> %s = %s )' % (GG('u', 'v'), GG('u', 'u')))], 'oveq1d', '( v = u -> %s = %s )' % (GGP, GGU))
gu = w.s([gf, umem], 'ffvelcdmd', '( %s -> %s e. CC )' % (Au, GU('u')))
ggu = w.s([gu, w.s([gu], 'cjcld', '( %s -> %s e. CC )' % (Au, CJ(GU('u'))))], 'mulcld', '( %s -> %s e. CC )' % (Au, GG('u', 'u')))
phic = w.s([w.s([n, w.inst('phicl')], 'syl', '( %s -> %s e. NN )' % (Au, PHI))], 'nncnd', '( %s -> %s e. CC )' % (Au, PHI))
ggpc = w.s([ggu, phic], 'mulcld', '( %s -> %s e. CC )' % (Au, GGU))
si = w.s([sub, crfin(w, Au), umem, ggpc], 'sumite', '( %s -> sum_ v e. %s if ( v = u , %s , 0 ) = %s )' % (Au, CRN, GGP, GGU))
w.qed([w.s([s1, si], 'eqtrd', '( %s -> sum_ v e. %s %s = %s )' % (Au, CRN, DELTA, GGU)), w.s([ggu, phic], 'mulcomd', '( %s -> %s = ( %s x. %s ) )' % (Au, GGU, PHI, GG('u', 'u')))], 'eqtrd', '( %s -> sum_ v e. %s %s = ( %s x. %s ) )' % (Au, CRN, DELTA, PHI, GG('u', 'u'))); run(w)

# ---- dchrparu
w = W('dchrparu', 'The unit-group Parseval identity (LargeSieve parseval_units): the sum over all Dirichlet characters mod N of the squared modulus of the character-linear form of G is phi ( N ) times the sum of the squared moduli of G over the coprime residues.')
n = w.s([], 'simpl', '( %s -> N e. NN )' % H0); gf = w.s([], 'simpr', '( %s -> G : %s --> CC )' % (H0, CRN))
