scl = w.s([w.s([crf], 'adantr', '( %s -> %s e. Fin )' % (Ax, CRN)), tcl], 'fsumcl', '( %s -> %s e. CC )' % (Ax, Sx))
a1 = w.s([w.s([scl, w.inst('absvalsq')], 'syl', '( %s -> %s = ( %s x. %s ) )' % (Ax, ABS2(Sx), Sx, CJ(Sx)))], 'sumeq2dv', '( %s -> sum_ x e. %s %s = sum_ x e. %s ( %s x. %s ) )' % (H0, DN, ABS2(Sx), DN, Sx, CJ(Sx)))
l2 = w.s([], 'dchrparulem2', '( %s -> sum_ x e. %s ( %s x. %s ) = %s )' % (H0, DN, Sx, CJ(Sx), SS(DELTA)))
Au = '( %s /\\ u e. %s )' % (H0, CRN)
l3 = w.s([], 'dchrparulem3', '( %s -> sum_ v e. %s %s = ( %s x. %s ) )' % (Au, CRN, DELTA, PHI, GG('u', 'u')))
a3 = w.s([l3], 'sumeq2dv', '( %s -> %s = sum_ u e. %s ( %s x. %s ) )' % (H0, SS(DELTA), CRN, PHI, GG('u', 'u')))
phic = w.s([w.s([n, w.inst('phicl')], 'syl', '( %s -> %s e. NN )' % (H0, PHI))], 'nncnd', '( %s -> %s e. CC )' % (H0, PHI))
gu = w.s([w.s([gf], 'adantr', '( %s -> G : %s --> CC )' % (Au, CRN)), w.s([], 'simpr', '( %s -> u e. %s )' % (Au, CRN))], 'ffvelcdmd', '( %s -> %s e. CC )' % (Au, GU('u')))
ggu = w.s([gu, w.s([gu], 'cjcld', '( %s -> %s e. CC )' % (Au, CJ(GU('u'))))], 'mulcld', '( %s -> %s e. CC )' % (Au, GG('u', 'u')))
a4 = w.s([crf, phic, ggu], 'fsummulc2', '( %s -> ( %s x. sum_ u e. %s %s ) = sum_ u e. %s ( %s x. %s ) )' % (H0, PHI, CRN, GG('u', 'u'), CRN, PHI, GG('u', 'u')))
a5 = w.s([w.s([w.s([gu, w.inst('absvalsq')], 'syl', '( %s -> %s = %s )' % (Au, ABS2(GU('u')), GG('u', 'u')))], 'sumeq2dv', '( %s -> sum_ u e. %s %s = sum_ u e. %s %s )' % (H0, CRN, ABS2(GU('u')), CRN, GG('u', 'u')))], 'oveq2d', '( %s -> ( %s x. sum_ u e. %s %s ) = ( %s x. sum_ u e. %s %s ) )' % (H0, PHI, CRN, ABS2(GU('u')), PHI, CRN, GG('u', 'u')))
c1 = w.s([a1, l2], 'eqtrd', '( %s -> sum_ x e. %s %s = %s )' % (H0, DN, ABS2(Sx), SS(DELTA)))
c2 = w.s([c1, a3], 'eqtrd', '( %s -> sum_ x e. %s %s = sum_ u e. %s ( %s x. %s ) )' % (H0, DN, ABS2(Sx), CRN, PHI, GG('u', 'u')))
c3 = w.s([c2, a4], 'eqtr4d', '( %s -> sum_ x e. %s %s = ( %s x. sum_ u e. %s %s ) )' % (H0, DN, ABS2(Sx), PHI, CRN, GG('u', 'u')))
